<?php

/**
 * @file
 * CiviCRM looks for its settings next to Drupal's settings.php. The real file
 * is generated by `cv core:install` on the private volume, so it survives
 * image rebuilds; this stub just loads it.
 */

if (is_file('/var/www/private/civicrm/civicrm.settings.php')) {
  require_once '/var/www/private/civicrm/civicrm.settings.php';
}
